// TH18 v1.00a Extra stage07 — Boss5 nonspell, source st07bs.ecl.txt:492-550,
// with st07bs.ecl.txt:552-577 (Boss5_at) and default.ecl.txt:2-14 (BossItem).
//
// Card timeline: phase_begin at card frame 0, OPENING_BUFFER 120 frames, then the
// real boss enters at (0,128) (source movePos 492/530). Source timerReset is at
// that entry; source activity slot 0 times out at 4200 frames. TIME_LIMIT 4380 =
// 120 buffer + 4200 activity + 60 tail.

const TIME_LIMIT: int = 4380;
const OPENING_BUFFER: int = 120;

// Source etSprite(type=12, color=14); TH18 48-shape vocabulary (bullet-types.md).
const TH18_ARROWHEAD: int = 544;

// ---------------------------------------------------------------------------
// Shell (validation.md): control carries the phase with no body, the real boss
// is spawned at the source entry position after the opening buffer.
// ---------------------------------------------------------------------------
async sub pattern() {
    wait(OPENING_BUFFER);
    // 529-530 movePos(0,128); lifeSet(19000) at 495. No drops in this card.
    _ = spawn_enemy(0fx, 128fx, 19000, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// ---------------------------------------------------------------------------
// Boss5 main context (492-550).
// ---------------------------------------------------------------------------
async sub source_enemy() {
    // 494-528: invuln/life, et+drop cleanup, timerReset, interrupt, animations,
    // scoring state. Shell boundary / pure reward / presentation per
    // transcription-policy; the 4200-frame slot-0 timeout is realised by the
    // fixed activity window below. Invuln is the shell's whole-segment value.
    set_invuln(65535);
    set_hitbox(24fx);       // 036-037 setHitbox(48,48) -> r=24 (enemy-state §1)
    set_hurtbox(20fx);      // 036-037 setHurtbox(40,40) -> r=20

    // 529-530: movePosTime(60,4,0,128) interpolates onto the entry point itself.
    wait(120);
    // 531 moveLimit(0,128,240,64): clamped per frame in arm_next_step().
    // 532-536: anmPlay/playSound (pure presentation) + 60-frame wait.
    wait(60);

    // 537-538: the two Boss5_at async contexts.
    // A=0: D=+0.15707964 (9deg), E=+0.02617994 (1.5deg), F=-0.013962634 (-0.8deg)
    // A=1: same magnitudes negated.
    spawn boss5_at(8192, 1.5deg, -146);
    spawn boss5_at(-8192, -1.5deg, 146);

    // 539-548: loop { wait100; moveRand(60,4,1.0); wait60;
    //                 wait100; moveRand(60,4,1.0); wait60; }
    // 12 full 320-frame cycles reach 4020; the 13th is cut at the 4200 timeout.
    for cycle in 0..12 {
        card_wait(100);
        card_move_rand();
        card_wait(60);
        card_wait(100);
        card_move_rand();
        card_wait(60);
    }
    card_wait(100);
    card_move_rand();
    card_wait(60);
    card_wait(20);          // 4200 from entry: slot-0 timeout (BossCard5 not run)
    loop { wait(1); }       // boss remains until the phase timer ends the card
}

// ---------------------------------------------------------------------------
// Boss5_at (552-577): one source emitter context. Source parameters A(0/1) are
// the two spawn() calls above; B=3 roads, C=16 layers.
// ---------------------------------------------------------------------------
async sub boss5_at(step5: int, omega: angle, layer_bam: int) {
    // 566: %G = %ANGLE_PLAYER, read once when the async context starts.
    // Keep x5 BAM so +9deg per volley is exact (9deg = 8192/5 BAM).
    var base5: int = (aim_player() as int) * 5;

    // 567: H = 10000; the 4200-frame segment timeout stops it first (402 volleys).
    for volley in 0..402 {
        // 555-565: emitter descriptor origin = enemy FINAL + etOffset(0,-24).
        var ox: fx = $self_x;
        var oy: fx = $self_y - 24fx;
        for q in 0..16 {                                // 574: layer q outer
            // 560 etSpeed(1.2,0): v(q) = 1.2 + (0-1.2)*q/15.
            var speed0: fx = 1.2fx * (15 - q) / 15;
            // 562 etEx VELTIME(60, r=3.0): delta = (3-v0)/60 along fixed angle.
            var accel: fx = (3fx - speed0) / 60fx;
            for i in 0..3 {                             // 574: road i inner
                // 604 etAngle + 607 etAim(5): alpha + pi/N + R(i) + q*delta,
                // pi/N = 60deg (10923 BAM), R(i) = i*65536/3.
                var ang: int = base5 / 5 + 10923 + layer_bam * q + (i * 65536) / 3;
                var ca: fx = cos(ang as angle);
                var sa: fx = sin(ang as angle);
                // 564 etDist(32) along each bullet's angle, then 561 ANIM
                // position -= 4*velocity (birth offset retained, birth animation
                // itself omitted per transcription-policy).
                var reach: fx = 32fx - 4fx * speed0;
                _ = fire(TH18_ARROWHEAD, 14, ox + reach * ca, oy + reach * sa,
                         speed0, ang as angle, BOSS5_AT(omega, accel), none);
            }
        }
        base5 = base5 + step5;                          // 571: %G = %G + %D
        wait(10);                                       // 573
    }
}

// 561 ANIM: birth position shift is folded into the spawn point above.
// 562 VELTIME: 60 frames of constant acceleration from the layer speed to 3.0
//   along the bullet's fixed direction (TH18 s <= -999990 = current angle).
// 563 ANGLE_ACCEL: 30 frames of speed += -0.03/frame and angle += omega/frame.
// All three source records have async=0, so they run serially.
xformdef BOSS5_AT(omega: angle, accel: fx) {
    set_accel(accel);
    wait(60);
    set_accel(-0.03fx);
    set_ang_vel(omega);
    wait(30);
    set_accel(0fx);
    set_ang_vel(0deg);
}

// ---------------------------------------------------------------------------
// moveRand(60,4,1.0) + moveLimit(0,128,240,64), TH18 movement.md recipe,
// BossCard2 reuse: direction inner region x +-60 / y 112..144, clamp
// x +-120 / y 96..160, speed 1.0*(1-k/60), mode0 linear.
// Enemy shared int slot 0 = next-step counter; fx slots 0/1 = unit direction.
// This card owns those slots (no other task writes them).
// ---------------------------------------------------------------------------
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 {
        var s: fx = (60 - k) as fx;
        speed = s / 60fx;
    }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}

sub card_move_rand() {
    // Source signed unit random * pi; values are unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }     // source normalises this branch
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;  // source WORD modulo 3
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
        // Deliberately not normalised before the vertical fabs tests.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Source +/-pi/2 guard, epsilon 0.05 rad -> nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}
